content:
:root {
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-light: #eff6ff;
  --color-secondary: #64748b;
  --color-secondary-hover: #475569;
  --color-bg-base: #f8fafc;
  --color-bg-card: #ffffff;
  --color-text-main: #0f172a;
  --color-text-muted: #64748b;
  --color-border: #e2e8f0;
  --color-success: #10b981;
  --color-success-bg: #ecfdf5;
  --color-danger: #ef4444;
  --color-danger-bg: #fef2f2;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-base);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* アプリ全体ラッパー */
.app-wrapper {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ヘッダー */
.header {
  background-color: var(--color-bg-card);
  border-bottom: 1px solid var(--color-border);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 10;
}

.header-content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.header-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

.header-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-muted);
}

/* メインコンテナ */
.container {
  max-width: 1200px;
  width: 100%;
  margin: 0 auto;
  padding: 1.5rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* コントロールツールバー */
.controls-bar {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  box-shadow: var(--shadow-sm);
}

.control-group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

/* ボタン群 */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease-in-out;
  user-select: none;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
}

.btn-secondary {
  background-color: #ffffff;
  border-color: var(--color-border);
  color: var(--color-secondary);
}

.btn-secondary:hover {
  background-color: #f1f5f9;
  color: var(--color-secondary-hover);
}

/* トグルスイッチ/チェックボックス */
.toggle-label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-main);
  cursor: pointer;
  user-select: none;
}

.toggle-checkbox {
  appearance: none;
  width: 2.25rem;
  height: 1.25rem;
  background-color: #cbd5e1;
  border-radius: 9999px;
  position: relative;
  outline: none;
  cursor: pointer;
  transition: background-color 0.2s ease;
  vertical-align: middle;
}

.toggle-checkbox::before {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 1rem;
  height: 1rem;
  background-color: #ffffff;
  border-radius: 50%;
  transition: transform 0.2s ease;
  box-shadow: var(--shadow-sm);
}

.toggle-checkbox:checked {
  background-color: var(--color-primary);
}

.toggle-checkbox:checked::before {
  transform: translateX(1rem);
}

/* KPIカードグリッド */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1rem;
}

.kpi-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.kpi-icon {
  width: 3rem;
  height: 3rem;
  border-radius: var(--radius-md);
  background-color: var(--color-primary-light);
  color: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  flex-shrink: 0;
}

.kpi-info {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.kpi-title {
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: 0.25rem;
}

.kpi-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-main);
  line-height: 1.2;
}

.kpi-unit {
  font-size: 0.875rem;
  font-weight: normal;
  color: var(--color-text-muted);
  margin-left: 0.25rem;
}

.kpi-subtext {
  font-size: 0.75rem;
  margin-top: 0.25rem;
  color: var(--color-text-muted);
}

/* グラフカード */
.chart-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  box-shadow: var(--shadow-sm);
}

.chart-card-header {
  margin-bottom: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.chart-title {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-text-main);
}

.chart-container {
  width: 100%;
  height: 380px;
}

/* Recharts カスタムツールチップ */
.custom-tooltip {
  background-color: rgba(15, 23, 42, 0.9);
  color: #ffffff;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-lg);
  font-size: 0.8125rem;
  backdrop-filter: blur(4px);
}

.tooltip-label {
  font-weight: 600;
  margin-bottom: 0.375rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
  padding-bottom: 0.25rem;
}

.tooltip-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 0.25rem;
}

.tooltip-val {
  font-weight: 600;
}

/* データテーブルカード */
.table-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  box-shadow: var(--shadow-sm);
}

.table-header {
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.table-title {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-text-main);
}

.table-responsive {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.data-table th,
.data-table td {
  padding: 0.75rem 0.875rem;
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}

.data-table th {
  background-color: #f8fafc;
  font-weight: 600;
  color: var(--color-text-muted);
}

.data-table tbody tr:hover {
  background-color: #f8fafc;
}

.table-input {
  width: 100px;
  padding: 0.375rem 0.5rem;
  font-size: 0.875rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: #ffffff;
  color: var(--color-text-main);
  text-align: right;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.table-input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

/* バッジと増減トレンド */
.table-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.5rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1;
}

.trend-up {
  color: var(--color-success);
  background-color: var(--color-success-bg);
}

.trend-down {
  color: var(--color-danger);
  background-color: var(--color-danger-bg);
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .header {
    padding: 1rem;
  }

  .container {
    padding: 1rem 0.75rem;
    gap: 1rem;
  }

  .controls-bar {
    flex-direction: column;
    align-items: stretch;
    padding: 1rem;
  }

  .control-group {
    justify-content: space-between;
  }

  .chart-container {
    height: 300px;
  }

  .table-input {
    width: 80px;
  }
}

export interface MonthlySalesItem {
  month: string;
  currentYear: number;
  previousYear: number;
  target: number;
}

export interface SummaryStats {
  totalSales: number;
  averageSales: number;
  maxMonth: string;
  maxSales: number;
  minMonth: string;
  minSales: number;
  achievementRate: number;
}

export interface SalesChartProps {
  data: MonthlySalesItem[];
  showPreviousYear: boolean;
  showTargetLine: boolean;
}

export interface SummaryCardsProps {
  stats: SummaryStats;
}

export interface MonthlyTableProps {
  data: MonthlySalesItem[];
  onUpdateSales: (
    monthIndex: number,
    field: 'currentYear' | 'target' | 'previousYear',
    value: number
  ) => void;
}

import {
  ResponsiveContainer,
  BarChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { SalesChartProps, MonthlySalesItem } from '../types';

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
  }>;
  label?: string;
}

function CustomTooltip({ active, payload, label }: CustomTooltipProps) {
  if (active && payload && payload.length) {
    return (
      <div className="custom-tooltip">
        <div className="tooltip-label">{label}</div>
        {payload.map((entry, index) => (
          <div key={`tooltip-${index}`} className="tooltip-item">
            <span style={{ color: entry.color }}>{entry.name}:</span>
            <span className="tooltip-val">{entry.value.toLocaleString()} 万円</span>
          </div>
        ))}
      </div>
    );
  }
  return null;
}

export default function SalesChart({
  data = [],
  showPreviousYear,
  showTargetLine,
}: SalesChartProps) {
  return (
    <div className="chart-card">
      <div className="chart-card-header">
        <h2 className="chart-title">月別売上推移グラフ</h2>
      </div>
      <div className="chart-container">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={data}
            margin={{ top: 20, right: 30, left: 10, bottom: 10 }}
          >
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
            <XAxis
              dataKey="month"
              tickLine={false}
              axisLine={{ stroke: '#cbd5e1' }}
              tick={{ fill: '#64748b', fontSize: 12 }}
            />
            <YAxis
              tickLine={false}
              axisLine={{ stroke: '#cbd5e1' }}
              tick={{ fill: '#64748b', fontSize: 12 }}
              tickFormatter={(val: number) => `${val.toLocaleString()}万`}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend
              verticalAlign="top"
              align="right"
              wrapperStyle={{ paddingBottom: '12px' }}
            />
            <Bar
              dataKey="currentYear"
              name="当年売上"
              fill="#3b82f6"
              radius={[4, 4, 0, 0]}
              maxBarSize={36}
            />
            {showPreviousYear && (
              <Bar
                dataKey="previousYear"
                name="前年実績"
                fill="#94a3b8"
                radius={[4, 4, 0, 0]}
                maxBarSize={36}
              />
            )}
            {showTargetLine && (
              <Line
                type="monotone"
                dataKey="target"
                name="目標値"
                stroke="#f97316"
                strokeWidth={3}
                dot={{ r: 4, fill: '#f97316' }}
                activeDot={{ r: 6 }}
              />
            )}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { ChangeEvent } from 'react';
import { MonthlyTableProps } from '../types';

export default function MonthlyTable({
  data = [],
  onUpdateSales,
}: MonthlyTableProps) {
  const handleInputChange = (
    index: number,
    field: 'currentYear' | 'target' | 'previousYear',
    e: ChangeEvent<HTMLInputElement>
  ) => {
    const rawVal = e.target.value;
    const num = Number(rawVal);
    onUpdateSales?.(index, field, isNaN(num) ? 0 : Math.max(0, num));
  };

  return (
    <div className="table-card">
      <div className="table-header">
        <h2 className="table-title">月別売上データ詳細・インライン編集</h2>
      </div>
      <div className="table-responsive">
        <table className="data-table">
          <thead>
            <tr>
              <th>月度</th>
              <th>当年売上 (万円)</th>
              <th>目標値 (万円)</th>
              <th>達成率</th>
              <th>前年実績 (万円)</th>
              <th>前年比</th>
              <th>ステータス</th>
            </tr>
          </thead>
          <tbody>
            {data.map((item, index) => {
              const achievementRate =
                item.target > 0 ? (item.currentYear / item.target) * 100 : 0;
              const yoyRate =
                item.previousYear > 0
                  ? ((item.currentYear - item.previousYear) / item.previousYear) * 100
                  : 0;
              const isAchieved = achievementRate >= 100;
              const isGrowth = yoyRate >= 0;

              return (
                <tr key={item.month}>
                  <td>
                    <strong>{item.month}</strong>
                  </td>
                  <td>
                    <input
                      type="number"
                      className="table-input"
                      value={item.currentYear}
                      onChange={(e) => handleInputChange(index, 'currentYear', e)}
                      min="0"
                      step="10"
                    />
                  </td>
                  <td>
                    <input
                      type="number"
                      className="table-input"
                      value={item.target}
                      onChange={(e) => handleInputChange(index, 'target', e)}
                      min="0"
                      step="10"
                    />
                  </td>
                  <td>
                    <span
                      className={`table-badge ${
                        isAchieved ? 'trend-up' : 'trend-down'
                      }`}
                    >
                      {achievementRate.toFixed(1)}%
                    </span>
                  </td>
                  <td>
                    <input
                      type="number"
                      className="table-input"
                      value={item.previousYear}
                      onChange={(e) => handleInputChange(index, 'previousYear', e)}
                      min="0"
                      step="10"
                    />
                  </td>
                  <td>
                    <span
                      className={`table-badge ${
                        isGrowth ? 'trend-up' : 'trend-down'
                      }`}
                    >
                      {isGrowth ? '+' : ''}
                      {yoyRate.toFixed(1)}%
                    </span>
                  </td>
                  <td>
                    <span
                      className={`table-badge ${
                        isAchieved ? 'trend-up' : 'trend-down'
                      }`}
                    >
                      {isAchieved ? '達成' : '要改善'}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { MonthlySalesItem, SummaryStats } from './types';
import SummaryCards from './components/SummaryCards';
import SalesChart from './components/SalesChart';
import MonthlyTable from './components/MonthlyTable';

const INITIAL_SALES_DATA: MonthlySalesItem[] = [
  { month: '1月', currentYear: 420, previousYear: 390, target: 400 },
  { month: '2月', currentYear: 380, previousYear: 360, target: 400 },
  { month: '3月', currentYear: 560, previousYear: 510, target: 500 },
  { month: '4月', currentYear: 450, previousYear: 430, target: 450 },
  { month: '5月', currentYear: 490, previousYear: 470, target: 480 },
  { month: '6月', currentYear: 520, previousYear: 480, target: 500 },
  { month: '7月', currentYear: 580, previousYear: 530, target: 550 },
  { month: '8月', currentYear: 460, previousYear: 490, target: 500 },
  { month: '9月', currentYear: 510, previousYear: 460, target: 500 },
  { month: '10月', currentYear: 540, previousYear: 520, target: 530 },
  { month: '11月', currentYear: 610, previousYear: 580, target: 580 },
  { month: '12月', currentYear: 680, previousYear: 640, target: 650 },
];

export default function App() {
  const [salesData, setSalesData] = useState<MonthlySalesItem[]>(INITIAL_SALES_DATA);
  const [showPreviousYear, setShowPreviousYear] = useState<boolean>(true);
  const [showTargetLine, setShowTargetLine] = useState<boolean>(true);

  const stats: SummaryStats = useMemo(() => {
    let totalSales = 0;
    let totalTarget = 0;
    let maxSales = -Infinity;
    let minSales = Infinity;
    let maxMonth = '';
    let minMonth = '';

    salesData.forEach((item) => {
      totalSales += item.currentYear;
      totalTarget += item.target;

      if (item.currentYear > maxSales) {
        maxSales = item.currentYear;
        maxMonth = item.month;
      }
      if (item.currentYear < minSales) {
        minSales = item.currentYear;
        minMonth = item.month;
      }
    });

    const averageSales = salesData.length > 0 ? totalSales / salesData.length : 0;
    const achievementRate = totalTarget > 0 ? (totalSales / totalTarget) * 100 : 0;

    return {
      totalSales,
      averageSales,
      maxMonth: maxMonth || '1月',
      maxSales: maxSales === -Infinity ? 0 : maxSales,
      minMonth: minMonth || '1月',
      minSales: minSales === Infinity ? 0 : minSales,
      achievementRate,
    };
  }, [salesData]);

  const handleUpdateSales = (
    monthIndex: number,
    field: 'currentYear' | 'target' | 'previousYear',
    value: number
  ) => {
    setSalesData((prev) => {
      const next = [...prev];
      next[monthIndex] = {
        ...next[monthIndex],
        [field]: value,
      };
      return next;
    });
  };

  const handleResetData = () => {
    setSalesData(INITIAL_SALES_DATA);
  };

  const handleRandomizeData = () => {
    const randomized = salesData.map((item) => {
      const base = 350 + Math.floor(Math.random() * 300);
      return {
        ...item,
        currentYear: base + Math.floor(Math.random() * 80) - 40,
        previousYear: base + Math.floor(Math.random() * 60) - 30,
        target: base + 20,
      };
    });
    setSalesData(randomized);
  };

  const handlePresetGrowth = () => {
    const growth = salesData.map((item, idx) => {
      const growthFactor = 1 + idx * 0.05;
      const base = Math.round(400 * growthFactor);
      return {
        ...item,
        currentYear: Math.round(base * 1.1),
        previousYear: base,
        target: Math.round(base * 1.05),
      };
    });
    setSalesData(growth);
  };

  return (
    <div className="app-wrapper">
      <header className="header">
        <div className="header-content">
          <h1 className="header-title">月別売上管理ダッシュボード</h1>
          <p className="header-subtitle">
            1月〜12月の売上推移・目標達成度・前年実績比較分析
          </p>
        </div>
      </header>

      <main className="container">
        <div className="controls-bar">
          <div className="control-group">
            <button
              type="button"
              className="btn btn-primary"
              onClick={handleRandomizeData}
            >
              🎲 データ乱数生成
            </button>
            <button
              type="button"
              className="btn btn-secondary"
              onClick={handlePresetGrowth}
            >
              📈 成長シナリオ適用
            </button>
            <button
              type="button"
              className="btn btn-secondary"
              onClick={handleResetData}
            >
              🔄 初期データに戻す
            </button>
          </div>

          <div className="control-group">
            <label className="toggle-label">
              <input
                type="checkbox"
                className="toggle-checkbox"
                checked={showPreviousYear}
                onChange={(e) => setShowPreviousYear(e.target.checked)}
              />
              前年実績の比較表示
            </label>
            <label className="toggle-label">
              <input
                type="checkbox"
                className="toggle-checkbox"
                checked={showTargetLine}
                onChange={(e) => setShowTargetLine(e.target.checked)}
              />
              目標値ラインの表示
            </label>
          </div>
        </div>

        <SummaryCards stats={stats} />

        <SalesChart
          data={salesData}
          showPreviousYear={showPreviousYear}
          showTargetLine={showTargetLine}
        />

        <MonthlyTable
          data={salesData}
          onUpdateSales={handleUpdateSales}
        />
      </main>
    </div>
  );
}
